import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import path, { join, relative, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { parseModuleSyntax, stripComments } from "./module-export-guard.mjs";
import { legacyArchitectureExceptions } from "./architecture-legacy-exceptions.mjs";

const sourcePattern = /\.(?:[cm]?[jt]sx?)$/i;
const extensions = [".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs"];
const normalise = (value) => value.replaceAll("\\", "/");

function isTestOrFixture(file) {
  return /(?:\.test\.|\.spec\.|\/tests?\/|\/__tests__\/|\/stories\/|\.stories\.)/.test(file);
}

function isProductionSource(file) {
  return file.startsWith("src/") && sourcePattern.test(file) && !isTestOrFixture(file);
}

function hasDirective(source, directive) {
  return stripComments(source).trimStart().startsWith(`"${directive}"`) || stripComments(source).trimStart().startsWith(`'${directive}'`);
}

function candidates(fromFile, specifier) {
  const base = specifier.startsWith("@/")
    ? `src/${specifier.slice(2)}`
    : path.posix.normalize(path.posix.join(path.posix.dirname(fromFile), specifier));
  return [base, ...extensions.map((extension) => `${base}${extension}`), ...extensions.map((extension) => `${base}/index${extension}`)];
}

function resolveModule(files, fromFile, specifier) {
  if (!(specifier.startsWith("@/") || specifier.startsWith("."))) return null;
  return candidates(fromFile, specifier).find((candidate) => files.has(candidate)) ?? null;
}

function importsServerRuntime(specifier, resolvedPath) {
  return specifier === "server-only" ||
    specifier === "@prisma/client" ||
    specifier.startsWith("@/server/") ||
    specifier.startsWith("@/lib/prisma") ||
    specifier.startsWith("@/lib/supabase/server") ||
    specifier.includes("prisma/generated") ||
    /^@\/modules\/[^/]+\/server(?:\/|$)/.test(specifier) ||
    resolvedPath?.startsWith("src/server/") ||
    /^src\/modules\/[^/]+\/server\//.test(resolvedPath ?? "");
}

function hasFixturePath(specifier, resolvedPath) {
  return [specifier, resolvedPath]
    .filter(Boolean)
    .map(normalise)
    .some((value) => /(?:^|\/)(?:tests\/fixtures|tests\/factories|stories\/fixtures|scripts\/seed|development\/fixtures)(?:\/|$)/.test(value.replace(/^@\//, "")));
}

function externalBindings(source) {
  const bindings = new Set();
  const code = stripComments(source);
  for (const match of code.matchAll(/(?:^|[;\n])\s*import\s+([^;"']+?)\s+from\s+(["'])([^"']+)\2/g)) {
    if (match[3].startsWith("@/") || match[3].startsWith(".")) continue;
    const clause = match[1].trim().replace(/^type\s+/, "");
    const defaultBinding = clause.split(/[,{]/)[0].trim();
    if (defaultBinding && !defaultBinding.startsWith("*")) bindings.add(defaultBinding);
    const named = clause.match(/\{([\s\S]*?)\}/)?.[1] ?? "";
    for (const item of named.split(",")) {
      const value = item.trim().replace(/^type\s+/, "");
      if (!value) continue;
      bindings.add((value.split(/\s+as\s+/)[1] ?? value.split(/\s+as\s+/)[0]).trim());
    }
  }
  return bindings;
}

function catalogTokens(source) {
  let code = stripComments(source);
  for (const { specifier } of parseModuleSyntax(source).imports) {
    if (!specifier.startsWith("@/") && !specifier.startsWith(".")) code = code.replaceAll(specifier, "");
  }
  return new Set([...code.matchAll(/\b[Cc]atalog(?!ue)[A-Za-z0-9_$]*/g)].map((match) => match[0]));
}

function internalApiCalls(source) {
  const code = stripComments(source);
  const calls = new Set();
  for (const match of code.matchAll(/\bfetch\s*\(\s*(?:new\s+URL\s*\(\s*)?(["'])(\/api\/[^"']*)\1/g)) calls.add(match[2]);
  return [...calls];
}

export function classifyArchitectureGraph({ files, previousFiles = {} }) {
  const fileMap = new Map(Object.entries(files).map(([file, source]) => [normalise(file), source]));
  const parsed = new Map([...fileMap].map(([file, source]) => [file, parseModuleSyntax(source)]));
  const actions = new Set([...fileMap].filter(([, source]) => hasDirective(source, "use server")).map(([file]) => file));
  const actionCache = new Map();
  function reachesAction(file, stack = new Set()) {
    if (actions.has(file)) return true;
    if (actionCache.has(file)) return actionCache.get(file);
    if (stack.has(file)) return false;
    const next = new Set(stack).add(file);
    const result = [...(parsed.get(file)?.namedReexports ?? []), ...(parsed.get(file)?.starReexports ?? [])]
      .map((entry) => resolveModule(fileMap, file, entry.specifier))
      .filter(Boolean)
      .some((target) => reachesAction(target, next));
    actionCache.set(file, result);
    return result;
  }

  const violations = [];
  for (const file of [...fileMap.keys()].sort()) {
    const source = fileMap.get(file);
    const imports = parsed.get(file).imports;
    const specifiers = new Set(imports.map(({ specifier }) => specifier));
    for (const entry of imports) {
      const resolvedPath = resolveModule(fileMap, file, entry.specifier);
      if (isProductionSource(file) && hasFixturePath(entry.specifier, resolvedPath)) {
        violations.push({ rule: "production-fixture-import", importer: file, imported: entry.specifier, detail: "Production source imports a test or development fixture." });
      }
      if (hasDirective(source, "use client") && importsServerRuntime(entry.specifier, resolvedPath)) {
        violations.push({ rule: "client-server-import", importer: file, imported: entry.specifier, detail: `Client module imports server runtime ${resolvedPath ?? entry.specifier}.` });
      }
      if (resolvedPath && reachesAction(resolvedPath) && specifiers.has("@tanstack/react-query")) {
        violations.push({ rule: "tanstack-server-action", importer: file, imported: resolvedPath, detail: "TanStack module imports a Server Action." });
      }
      if (resolvedPath && reachesAction(resolvedPath) && /^src\/app\/.+\/route\.[cm]?[jt]sx?$/.test(file)) {
        violations.push({ rule: "route-handler-server-action", importer: file, imported: resolvedPath, detail: actions.has(resolvedPath) ? "Route Handler imports a Server Action." : "Route Handler imports a Server Action through a re-export." });
      }
    }

    if (isProductionSource(file) && file.startsWith("src/app/") && !/\/route\.[cm]?[jt]sx?$/.test(file) && !hasDirective(source, "use client") && !hasDirective(source, "use server")) {
      for (const apiPath of internalApiCalls(source)) violations.push({ rule: "server-component-internal-api", importer: file, detail: `Server Component calls internal API ${apiPath} instead of its domain query.` });
    }

    if (isProductionSource(file)) {
      const previousTokens = catalogTokens(previousFiles[file] ?? "");
      const ignored = externalBindings(source);
      for (const token of catalogTokens(source)) {
        if (!previousTokens.has(token) && !ignored.has(token)) violations.push({ rule: "american-catalogue-language", importer: file, detail: `New American catalogue identifier: ${token}.` });
      }
    }
  }
  return violations;
}

function listFiles(directory, prefix = "") {
  if (!existsSync(directory)) return [];
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const absolute = join(directory, entry.name);
    const repoPath = normalise(join(prefix, entry.name));
    return entry.isDirectory() ? listFiles(absolute, repoPath) : sourcePattern.test(entry.name) ? [repoPath] : [];
  });
}

function previousSource(root, file) {
  try {
    return execFileSync("git", ["show", `HEAD^:${file}`], { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
  } catch {
    return "";
  }
}

export function runArchitectureGuard(root = process.cwd()) {
  const sourceFiles = listFiles(join(root, "src"), "src");
  const files = Object.fromEntries(sourceFiles.map((file) => [file, readFileSync(join(root, file), "utf8")]));
  let changedFiles = new Set();
  try {
    changedFiles = new Set(execFileSync("git", ["diff", "--name-only", "HEAD^", "--", "src"], { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).split(/\r?\n/).map(normalise).filter(Boolean));
  } catch {
    // An empty previous source fails new-debt checks closed when Git history is unavailable.
  }
  const previousFiles = Object.fromEntries(sourceFiles.map((file) => [file, changedFiles.has(file) ? previousSource(root, file) : files[file]]));
  const violations = classifyArchitectureGraph({ files, previousFiles });
  const warnings = [];
  const importsByFile = new Map(sourceFiles.map((file) => [file, new Set(parseModuleSyntax(files[file]).imports.map(({ specifier }) => specifier))]));
  const exceptionEdges = new Set(legacyArchitectureExceptions.map((entry) => `${entry.importer}->${entry.imported}`));

  for (const entry of legacyArchitectureExceptions) {
    if (!importsByFile.get(entry.importer)?.has(entry.imported)) violations.push({ rule: "stale-architecture-exception", importer: entry.importer, imported: entry.imported, detail: `Stale architecture exception: ${entry.importer} -> ${entry.imported}.` });
  }

  for (const file of sourceFiles.filter(isProductionSource)) {
    const previousImports = new Set(parseModuleSyntax(previousFiles[file] ?? "").imports.map(({ specifier }) => specifier));
    for (const specifier of importsByFile.get(file)) {
      const edge = `${file}->${specifier}`;
      const authCompatibility = specifier === "@/server/auth/session" || specifier === "@/server/auth/profile" || specifier.startsWith("@/features/storefront/shared/storefront-auth-");
      const checkoutCompatibility = /^(?:src\/app\/|src\/stores\/|src\/modules\/|src\/server\/)/.test(file) && specifier.startsWith("@/features/storefront/checkout/");
      if ((authCompatibility || checkoutCompatibility) && !exceptionEdges.has(edge)) violations.push({ rule: "undocumented-compatibility-edge", importer: file, imported: specifier, detail: `Undocumented compatibility edge: ${file} -> ${specifier}.` });
      const newImport = !previousImports.has(specifier);
      if (newImport && specifier.startsWith("@/features/storefront/") && /^(?:src\/app\/|src\/stores\/|src\/modules\/|src\/server\/)/.test(file) && !exceptionEdges.has(edge)) violations.push({ rule: "target-ownership-leak", importer: file, imported: specifier, detail: `New target ownership leak imports legacy ${specifier}.` });
      if (newImport && file.startsWith("src/modules/") && specifier.startsWith("@/features/") && !exceptionEdges.has(edge)) violations.push({ rule: "domain-feature-leak", importer: file, imported: specifier, detail: `New domain module dependency on legacy feature ${specifier}.` });
    }
    if (/^src\/app\/api\//.test(file) && !file.startsWith("src/app/api/v1/") && !file.startsWith("src/app/api/health/") && !file.startsWith("src/app/api/internal/")) violations.push({ rule: "unversioned-api-route", importer: file, detail: "Machine-readable API route is outside /api/v1." });
    const lines = files[file].split(/\r?\n/).length;
    if (lines > 800) violations.push({ rule: "god-module", importer: file, detail: `${file} has ${lines} lines; split the god module.` });
    else if (lines > 600) warnings.push(`${file} has ${lines} lines and needs a responsibility review.`);
  }

  const requiredFiles = ["src/stores/cart.store.ts", "src/stores/saved-items.store.ts", "src/stores/storefront-ui.store.ts", "src/providers/providers.tsx", "src/modules/products/storefront/catalogue-contract.ts", "src/modules/products/server/storefront/catalogue-projection.ts", "src/modules/products/client/storefront-catalogue.ts", "src/app/api/v1/products/route.ts"];
  for (const file of requiredFiles) if (!existsSync(join(root, file))) violations.push({ rule: "missing-target-file", importer: file, detail: `Required target-architecture file is missing: ${file}.` });
  return { scanned: sourceFiles.length, serverActions: Object.values(files).filter((source) => hasDirective(source, "use server")).length, violations, warnings };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const result = runArchitectureGuard(process.cwd());
  const lines = ["## Architecture guard", "", `- Source files scanned: ${result.scanned}`, `- Server Action modules indexed: ${result.serverActions}`, `- Errors: ${result.violations.length}`, `- Warnings: ${result.warnings.length}`];
  if (result.warnings.length) lines.push("", "### Warnings", ...result.warnings.map((warning) => `- ${warning}`));
  if (result.violations.length) lines.push("", "### Failures", ...result.violations.map((violation) => `- [${violation.rule}] ${violation.importer}${violation.imported ? ` -> ${violation.imported}` : ""}: ${violation.detail}`));
  process.stdout.write(`${lines.join("\n")}\n`);
  if (result.violations.length) process.exitCode = 1;
}

const phase7SessionImporters = [
  "src/app/storefront-route-boundary.tsx",
  "src/app/auth/sign-in/page.tsx",
  "src/app/admin/layout.tsx",
  "src/app/admin/inventory/page.tsx",
  "src/app/(storefront)/account/profile/page.tsx",
  "src/app/(storefront)/account/profile/actions.ts",
  "src/app/(storefront)/account/orders/page.tsx",
  "src/app/(storefront)/account/orders/[orderNumber]/page.tsx",
  "src/app/(storefront)/account/orders/[orderNumber]/items/[orderLineId]/review/actions.ts",
  "src/app/(storefront)/account/orders/[orderNumber]/items/[orderLineId]/review/page.tsx",
  "src/lib/http/auth.ts",
  "src/modules/customers/server/commands.ts",
  "src/modules/holds/server/commands.ts",
  "src/modules/inventory/server/adjust-stock.ts",
  "src/modules/inventory/server/stock-write.ts",
  "src/modules/orders/server/offline-sale-checkout.ts",
  "src/modules/orders/server/offline-sale-draft.ts",
  "src/modules/orders/server/offline-sale.ts",
  "src/modules/orders/server/transition-order.ts",
  "src/modules/products/server/lifecycle-commands.ts",
  "src/modules/products/server/product-commands.ts",
  "src/modules/products/server/rules.ts",
  "src/modules/products/server/taxonomy-commands.ts",
  "src/modules/returns/server/commands.ts",
  "src/modules/settings/server/commands.ts",
];

const phase7ProfileImporters = [
  "src/app/auth/callback/route.ts",
  "src/server/auth/session.ts",
];

const phase7StorefrontAuthProviderImporters = [
  "src/app/storefront-client-boundary.tsx",
  "src/modules/storefront-shell/ui/site-chrome.tsx",
  "src/modules/storefront-shell/ui/storefront-account-menu.tsx",
];

const phase7StorefrontAuthCompositionEdges = [
  {
    importer: "src/app/storefront-client-boundary.tsx",
    imported: "@/features/storefront/shared/storefront-auth-dialog-host",
  },
  {
    importer: "src/app/storefront-client-boundary.tsx",
    imported: "@/features/storefront/shared/storefront-auth-session",
  },
  {
    importer: "src/app/storefront-route-boundary.tsx",
    imported: "@/features/storefront/shared/storefront-auth-session",
  },
];

const phase8Edges = [
  {
    importer: "src/app/(storefront)/checkout/page.tsx",
    imported: "@/features/storefront/checkout/checkout-flow-v2",
  },
  {
    importer: "src/app/(storefront)/order-confirmation/page.tsx",
    imported: "@/features/storefront/checkout/order-receipt",
  },
];

const phase7Reason =
  "Phase 1-6 reuses the inherited session boundary; auth ownership moves in Phase 7.";
const phase7ProfileReason =
  "Phase 1-6 reuses the inherited profile boundary; auth ownership moves in Phase 7.";
const phase7StorefrontProviderReason =
  "Phase 1-6 reuses the inherited storefront auth provider; auth ownership moves in Phase 7.";
const phase8Reason =
  "Phase 2 preserves the existing checkout presentation; settlement authority moves in Phase 8.";

export const legacyArchitectureExceptions = Object.freeze([
  ...phase7SessionImporters.map((importer) =>
    Object.freeze({
      importer,
      imported: "@/server/auth/session",
      kind: "phase-7-auth",
      reason: phase7Reason,
      owner: "domain-engineer",
      removalPhase: 7,
    }),
  ),
  ...phase7ProfileImporters.map((importer) =>
    Object.freeze({
      importer,
      imported: "@/server/auth/profile",
      kind: "phase-7-auth",
      reason: phase7ProfileReason,
      owner: "domain-engineer",
      removalPhase: 7,
    }),
  ),
  ...phase7StorefrontAuthProviderImporters.map((importer) =>
    Object.freeze({
      importer,
      imported: "@/features/storefront/shared/storefront-auth-provider",
      kind: "phase-7-auth",
      reason: phase7StorefrontProviderReason,
      owner: "domain-engineer",
      removalPhase: 7,
    }),
  ),
  ...phase7StorefrontAuthCompositionEdges.map((edge) =>
    Object.freeze({
      ...edge,
      kind: "phase-7-auth",
      reason: phase7StorefrontProviderReason,
      owner: "domain-engineer",
      removalPhase: 7,
    }),
  ),
  ...phase8Edges.map((edge) =>
    Object.freeze({
      ...edge,
      kind: "phase-8-checkout",
      reason: phase8Reason,
      owner: "ui-engineer",
      removalPhase: 8,
    }),
  ),
]);

export const legacyTopLevelServerFiles = new Set([
  "src/server/auth/session.ts",
  "src/server/auth/profile.ts",
]);

export const legacyProductTypeOnlyEdge = Object.freeze({
  importer: "src/features/storefront/shared/storefront-auth-dialog.tsx",
  imported: "@/features/storefront/shared/catalogue-data",
  shim: "src/features/storefront/shared/catalogue-data.ts",
});

const edgeKeys = legacyArchitectureExceptions.map(
  ({ importer, imported }) => `${importer}->${imported}`,
);
if (new Set(edgeKeys).size !== edgeKeys.length) {
  throw new Error("Duplicate legacy architecture exception edge.");
}

for (const entry of legacyArchitectureExceptions) {
  if (
    entry.importer.length === 0 ||
    entry.imported.length === 0 ||
    ![7, 8].includes(entry.removalPhase) ||
    !["domain-engineer", "ui-engineer"].includes(entry.owner)
  ) {
    throw new Error(`Invalid legacy architecture exception: ${entry.importer}->${entry.imported}`);
  }
}

import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

const root = process.cwd();
const errors = [];

function read(path) {
  const absolute = join(root, path);
  if (!existsSync(absolute)) {
    errors.push(`Required Phase 5 contract is missing: ${path}`);
    return "";
  }
  return readFileSync(absolute, "utf8");
}

function listFiles(directory, prefix = "") {
  if (!existsSync(directory)) return [];
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const relative = join(prefix, entry.name).replaceAll("\\", "/");
    const absolute = join(directory, entry.name);
    return entry.isDirectory() ? listFiles(absolute, relative) : [relative];
  });
}

const canonicalResult = read("src/lib/errors/index.ts");
const compatibilityResult = read("src/lib/admin/shared/result.ts");
const authErrors = read("src/lib/auth/auth-errors.ts");
const authSchemas = read("src/lib/auth/auth-schemas.ts");
const authActions = read("src/app/auth/actions.ts");
const authCallback = read("src/app/auth/callback/route.ts");
const googleAuth = read("src/app/auth/google/route.ts");
const authErrorPage = read("src/app/auth/error/page.tsx");
const authProvider = read("src/features/storefront/shared/storefront-auth-provider.tsx");
const authRedirects = read("src/lib/auth/server/redirects.ts");
const authDiagnostics = read("src/lib/auth/server/auth-provider-diagnostics.ts");
const reviewActions = read(
  "src/app/(storefront)/account/orders/[orderNumber]/items/[orderLineId]/review/actions.ts",
);
const productSchema = read("src/modules/products/schema.ts");
const productsRoute = read("src/app/api/v1/admin/products/route.ts");
const productRoute = read("src/app/api/v1/admin/products/[id]/route.ts");
const productArchiveRoute = read("src/app/api/v1/admin/products/[id]/archive/route.ts");
const productRestoreRoute = read("src/app/api/v1/admin/products/[id]/restore/route.ts");
const productTaxonomyRoute = read("src/app/api/v1/admin/products/taxonomy/[id]/route.ts");
const browserContract = read("tests/e2e/error-validation.spec.ts");

if (!canonicalResult.includes("export type Result<")) {
  errors.push("The canonical Result implementation must remain in src/lib/errors/index.ts.");
}
if (
  /export\s+type\s+Result\s*</.test(compatibilityResult) ||
  /function\s+(?:ok|err)\s*</.test(compatibilityResult)
) {
  errors.push("src/lib/admin/shared/result.ts must not define a second Result implementation.");
}
if (!compatibilityResult.includes('from "@/lib/errors"')) {
  errors.push("The legacy admin Result path may only re-export the canonical helper while callers migrate.");
}

const resultDefinitions = listFiles(join(root, "src"), "src")
  .filter((path) => /\.[cm]?[jt]sx?$/.test(path))
  .filter((path) => /export\s+type\s+Result\s*</.test(readFileSync(join(root, path), "utf8")));
if (resultDefinitions.length !== 1 || resultDefinitions[0] !== "src/lib/errors/index.ts") {
  errors.push(`Expected one Result implementation; found ${resultDefinitions.join(", ") || "none"}.`);
}

if (!authErrors.includes("mapAuthProviderError") || !authErrors.includes("authFlowErrorCodes")) {
  errors.push("Auth provider failures must map through typed allow-listed error codes.");
}
if (!authSchemas.includes("passwordSignInSchema") || !authSchemas.includes("passwordSignUpSchema")) {
  errors.push("Password Server Actions must use the canonical Zod auth schemas.");
}
if (!authSchemas.includes("terms:") || !authProvider.includes('formData.set("terms"')) {
  errors.push("Terms acceptance must be enforced at the Server Action boundary, not only in client UI.");
}
if (!authActions.includes("safeParse") || !authActions.includes("mapAuthProviderError")) {
  errors.push("Password auth actions must Zod-parse input and map provider failures.");
}
if (!authActions.includes("logAuthProviderFailure")) {
  errors.push("Auth provider failures must retain structured server-side diagnostics.");
}
if (/error\.message|\.message\.toLowerCase|includes\(["']invalid/.test(authActions)) {
  errors.push("Password auth actions must not branch on or expose provider error messages.");
}
if (/withAuthErrorPath\([^,]*\.message/.test(authCallback + googleAuth + authActions)) {
  errors.push("Auth redirects must never carry raw provider error messages.");
}
if (/params\.message|searchParams:[\s\S]*message\?/.test(authErrorPage)) {
  errors.push("The auth error page must render allow-listed codes, not arbitrary message query values.");
}
if (!authRedirects.includes("code,") || authRedirects.includes("message,")) {
  errors.push("Auth error redirects must serialize an allow-listed code only.");
}
if (
  !authDiagnostics.includes('import "server-only"') ||
  !authDiagnostics.includes("logger.warn") ||
  !authDiagnostics.includes("providerCode") ||
  !authDiagnostics.includes("providerStatus") ||
  !authDiagnostics.includes("providerErrorName")
) {
  errors.push("Auth diagnostics must remain server-only and log structured provider metadata.");
}
if (/error\.message|providerMessage|rawMessage/.test(authDiagnostics)) {
  errors.push("Auth diagnostics must not log raw provider messages.");
}
if (
  !browserContract.includes("invalid-credentials") ||
  !browserContract.includes("raw-provider-detail") ||
  !browserContract.includes("toHaveCount(0)")
) {
  errors.push("Browser coverage must prove arbitrary auth query text is not reflected to users.");
}

if (!reviewActions.includes("reviewIdentifiersSchema.safeParse")) {
  errors.push("Review actions must Zod-parse order and line identifiers.");
}
if (
  /throw new Error\(identity\.state\.message\)|throw new Error\(["']This review link/.test(
    reviewActions,
  )
) {
  errors.push("Expected review auth/link failures must return typed action state instead of throwing.");
}
if (
  !productSchema.includes("productEditorDraftSchema") ||
  !productSchema.includes("productMutationSchema") ||
  !productsRoute.includes("parseJsonBody(request, productMutationSchema)") ||
  !productRoute.includes("parseJsonBody(request, productMutationSchema)")
) {
  errors.push("Product create and update routes must validate payloads and intents with the domain schema.");
}
if (
  !productSchema.includes("productIdSchema") ||
  !productRoute.includes("productIdSchema.safeParse") ||
  !productArchiveRoute.includes("productIdSchema.safeParse") ||
  !productRestoreRoute.includes("productIdSchema.safeParse")
) {
  errors.push("Product lifecycle routes must validate product identifiers at the transport boundary.");
}
if (
  !productSchema.includes("productTaxonomyIdSchema") ||
  !productSchema.includes("productTaxonomyRenameSchema") ||
  !productTaxonomyRoute.includes("productTaxonomyIdSchema.safeParse") ||
  !productTaxonomyRoute.includes("parseJsonBody(request, productTaxonomyRenameSchema)")
) {
  errors.push("Product taxonomy routes must validate encoded identifiers and names.");
